Use ASP.NET Core's **`WebApplicationFactory<TEntryPoint>`** from the `Microsoft.AspNetCore.Mvc.Testing` package. It hosts your app in-memory — no real ports, no real server.

### Setup

```bash
dotnet add tests/MyMcp.Tests package Microsoft.AspNetCore.Mvc.Testing
```

### Test pattern

```csharp
using Microsoft.AspNetCore.Mvc.Testing;
using System.Net.Http.Json;
using System.Text.Json;

public class McpIntegrationTests
    : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsServerCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2.0", body.GetProperty("jsonrpc").GetString());
        Assert.True(body.TryGetProperty("result", out var result));
        Assert.True(result.TryGetProperty("capabilities", out _));
    }

    [Fact]
    public async Task ToolsCall_ExecutesTool()
    {
        // 1. Initialize session first
        var init = new { jsonrpc = "2.0", id = 1, method = "initialize",
            @params = new { protocolVersion = "2025-03-26",
                capabilities = new { }, clientInfo = new { name = "test", version = "1.0" } } };
        var initResp = await _client.PostAsJsonAsync("/mcp", init);
        // Grab Mcp-Session-Id if your server uses it
        var sessionId = initResp.Headers.TryGetValues("Mcp-Session-Id", out var vals)
            ? vals.First() : null;

        // 2. Call a tool
        var toolCall = new { jsonrpc = "2.0", id = 2, method = "tools/call",
            @params = new { name = "my-tool", arguments = new { input = "hello" } } };

        using var req = new HttpRequestMessage(HttpMethod.Post, "/mcp");
        req.Content = JsonContent.Create(toolCall);
        if (sessionId != null) req.Headers.Add("Mcp-Session-Id", sessionId);

        var resp = await _client.SendAsync(req);
        resp.EnsureSuccessStatusCode();

        var body = await resp.Content.ReadFromJsonAsync<JsonElement>();
        var content = body.GetProperty("result").GetProperty("content");
        Assert.True(content.GetArrayLength() > 0);
    }
}
```

### Key points

| Concern | Solution |
|---|---|
| **No real port** | `WebApplicationFactory` hosts in-memory via `TestServer` |
| **Session state** | Forward the `Mcp-Session-Id` header between requests |
| **SSE streams** | Read with `HttpCompletionOption.ResponseHeadersRead` + `ReadAsStreamAsync()` and parse `text/event-stream` lines |
| **DI overrides** | Use `factory.WithWebHostBuilder(b => b.ConfigureServices(...))` to swap dependencies |
| **`Program` visibility** | Add `<InternalsVisibleTo Include="YourTestProject" />` or a partial class if `Program` is implicit |

This gives you full HTTP-level fidelity (middleware, routing, serialization) with unit-test speed.
